+const SEAM_PHI: f64 = -std::f64::consts::FRAC_PI_2;
+
+fn feeds(t: &camcraft_motion::cl::Toolpath) -> impl Iterator<Item = &camcraft_motion::cl::Move> {
+    t.moves.iter().filter(|m| m.kind == MoveKind::Feed)
